/**
 * PSE Disclosures Provider
 *
 * Reads data/pse-disclosures.json (generated by
 * scripts/scrape-pse-disclosures.ts, which scrapes each company's most
 * recent real disclosures from PSE Edge — see PSEEdgeScraper.ts's
 * fetchCompanyDisclosures). These are genuine PSE filings — Press
 * Releases, Material Information/Transactions, insider-transaction forms,
 * results announcements — each with a link to the real filing on PSE Edge.
 *
 * There is no synthetic fallback here: a symbol with no scraped
 * disclosures simply gets an empty array, and the UI renders an honest
 * "no disclosures available" state rather than templated placeholder
 * headlines (the fastify apiRouter previously fabricated fake news items
 * like source: "Lensory Research" — that fabrication has been removed in
 * favor of this real feed or nothing at all).
 */
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

export interface PseDisclosureRecord {
  symbol: string;
  companyName: string;
  formType: string;      // e.g. "4-30" (Material Info), "4-31" (Press Release),
  title: string;         // the disclosure category shown in PSE Edge's table,
  filingDate: string;    // e.g. "Jul 28, 2026 03:57 PM",
  edgeNo: string;
  sourceUrl: string;
}

type DisclosureMap = Record<string, PseDisclosureRecord[]>;

let disclosureCache: DisclosureMap | null = null;

function loadDisclosureMap(): DisclosureMap {
  if (disclosureCache !== null) return disclosureCache;
  let loaded: DisclosureMap = {};
  try {
    const raw = readFileSync(resolve(process.cwd(), 'data/pse-disclosures.json'), 'utf-8');
    loaded = JSON.parse(raw).results ?? {};
  } catch {
    // File not generated yet (scripts/scrape-pse-disclosures.ts hasn't been
    // run) — treat as "no real data available", not an error.
  }
  disclosureCache = loaded;
  return loaded;
}

/** Real recent disclosures for a symbol, or an empty array if none are
 * available. Never fabricated — callers should render an honest empty
 * state rather than placeholder headlines. */
export function loadPseDisclosures(symbol: string): PseDisclosureRecord[] {
  return loadDisclosureMap()[symbol.toUpperCase()] ?? [];
}

/** Whether a symbol has real disclosure data in the snapshot. */
export function hasPseDisclosures(symbol: string): boolean {
  return (loadDisclosureMap()[symbol.toUpperCase()]?.length ?? 0) > 0;
}
